changeSet.sql:
ALTER TABLE modeling_model_release_candidate_entry DROP CONSTRAINT ck_model_release_candidate_entry_build_snapshot;
UPDATE modeling_model_release_candidate_entry e SET active_claim_key = NULL FROM modeling_model_release_candidate c WHERE c.tenant_id = e.tenant_id AND c.id = e.candidate_id AND c.status = 'PUBLISHED' AND e.status = 'PUBLISHED' AND e.active_claim_key IS NOT NULL;
ALTER TABLE modeling_model_release_candidate_entry ADD CONSTRAINT ck_model_release_candidate_entry_build_snapshot CHECK ( ( implementation_revision IS NULL AND implementation_checksum IS NULL AND dbt_unique_id IS NULL AND target_identifier IS NULL AND artifact_bundle_checksum IS NULL AND dependency_snapshot_checksum IS NULL AND ( active_claim_key IS NULL OR ( status IN ('DRAFT', 'BUILDING') AND active_claim_key ~ '^[0-9a-f]{64}$' ) ) ) OR ( implementation_id IS NOT NULL AND implementation_revision > 0 AND implementation_checksum ~ '^[0-9a-f]{64}$' AND dbt_unique_id ~ '^model\.[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*$' AND target_identifier ~ '^[A-Za-z_][A-Za-z0-9_]*$' AND artifact_bundle_checksum ~ '^[0-9a-f]{64}$' AND dependency_snapshot_checksum ~ '^[0-9a-f]{64}$' AND ( (status = 'CANCELLED' AND active_claim_key IS NULL) OR ( status IN ('REJECTED', 'ROLLED_BACK', 'STALE', 'PUBLISHED') AND ( active_claim_key IS NULL OR active_claim_key ~ '^[0-9a-f]{64}$' ) ) OR ( status NOT IN ('CANCELLED', 'REJECTED', 'ROLLED_BACK', 'STALE', 'PUBLISHED') AND active_claim_key ~ '^[0-9a-f]{64}$' ) ) ) );

rollback.sql:
DO $$
BEGIN
    LOCK TABLE modeling_model_release_candidate_entry IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (
        SELECT 1
          FROM modeling_model_release_candidate_entry
         WHERE status = 'PUBLISHED'
           AND active_claim_key IS NULL
    ) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_PUBLISHED_CANDIDATE_CLAIM_RELEASE_EXISTS';
    END IF;
END $$;
